clean_output:
:
            list: List of tokens.

        Raises:
            ValueError: If the overlap between two consecutive labels is greater than ``overlap_threshold``.
        """
        tokenized_labels = [label.tokenized() for label in self]
        tokens = []
        for tokenized_label in tokenized_labels:
            if not tokenized_label:
                continue
            if tokens and tokens[-1] and (
                tokens[-1][-1] in tokenized_label or tokenized_label[0] in tokens[-1]
            ):
                raise ValueError('Overlapping labels')
            tokens.extend(tokenized_label)
        return delimiter.join(tokens)
